"""
    Description
    ----------
    Check to see if the target string is the end of the string.

    Parameters
    ----------
    string : str - string to check end of\n
    target : str - string to search for

    Returns
    ----------
    bool - True if target is the end of string, False otherwise

    Examples
    ----------
    >>> endswith('Sample string', 'ing')
    -> True
    >>> endswith('abcabcabc', 'abcd')
    -> False
    """
def endswith(string: Any, target: Any) -> object {
    if not isinstance(string, str) {
        raise TypeError("param 'string' must be a string");
    }
    if not isinstance(target, str) {
        raise TypeError("param 'target' must be a string");
    }
    return (string[(len(target) * -1):] == target);
}

"""
    Accounts for non-empirical chemical formulas by taking in the compositional array generated by _create_compositional_array_() and returning a consolidated array of dictionaries with no repeating elements

    :param elemental_array: an elemental array generated from _create_compositional_array_()
    :return: an array of element dictionaries
    """
def _consolidate_elemental_array_(elemental_array: Any) -> object {
    condensed_array = [];
    for e in elemental_array {
        exists = False;
        for k in condensed_array {
            if (k["symbol"] == e["symbol"]) {
                exists = True;
                k["occurances"] += e["occurances"];
                break;
            }
        }
        if not exists {
            condensed_array.append(e);
        }
    }
    return condensed_array;
}

